do $$
declare k text;
begin
  select decrypted_secret into k from vault.decrypted_secrets where name = 'biomarker_lock_key' limit 1;
  if k is null or k = '' then raise exception 'Biomarker unlock key unavailable; aborting'; end if;
  perform set_config('app.biomarker_unlock', k, true);
end $$;

create table if not exists bioaudit.tpl(k text primary key, j text not null);
revoke all on table bioaudit.tpl from public;

create or replace function bioaudit.expand(e jsonb) returns jsonb language plpgsql stable as $f$
declare mt text; ct text; mj jsonb := '{}'::jsonb; cj jsonb := '{}'::jsonb; o text := coalesce(e->>'O', '');
begin
  select j into mt from bioaudit.tpl where k = 'm:' || coalesce(e->>'m', '');
  select j into ct from bioaudit.tpl where k = 'c:' || coalesce(e->>'cx', '');
  if mt is not null then mj := replace(mt, '{O}', o)::jsonb; end if;
  if ct is not null then cj := replace(ct, '{O}', o)::jsonb; end if;
  return mj || cj || e || jsonb_build_object('force', coalesce(mj->'force', '{}'::jsonb) || coalesce(cj->'force', '{}'::jsonb) || coalesce(e->'force', '{}'::jsonb));
end $f$;

create or replace function bioaudit.fill_tpl(p_rows jsonb, p_d jsonb default '{}'::jsonb) returns jsonb language sql as $f$
  select bioaudit.fill((select jsonb_agg(bioaudit.expand(e)) from jsonb_array_elements(p_rows) e), p_d)
$f$;
revoke all on function bioaudit.expand(jsonb) from public;
revoke all on function bioaudit.fill_tpl(jsonb, jsonb) from public;

insert into bioaudit.tpl(k, j) values
('m:PCR', $j${"w":"A molecular (PCR) test that looks for genetic material from {O} in your sample.","a":"How and when the sample was taken, recent antibiotic or antiviral treatment, and very low amounts of the organism early or late in an infection.","s":"A detected result shows that {O} is present in the sample. PCR is very sensitive, so results are read alongside your symptoms.","u":"Qualitative (detected or not detected)","rr":{"both":{"normal":["Not detected","Negative","No genetic material from {O} was found."],"high":["Detected","Positive","The test found {O} in the sample."]}},"gl":"Not detected means no genetic material from {O} was found. A sample taken very early or late in an infection can miss it.","gh":"Detected means the test found {O} in your sample. Your clinician will decide whether it explains your symptoms and needs treatment.","hi":"infection with {O}"}$j$),
('m:IGG', $j${"w":"The level of IgG antibodies to {O} in your blood. IgG antibodies usually appear a few weeks after infection or vaccination and can last for years.","a":"Time since infection or vaccination, a weakened immune system, recent blood transfusion or immunoglobulin treatment, and the laboratory method used.","s":"A positive IgG result shows past infection with {O}, or vaccination where a vaccine exists. On its own it does not show when the infection happened.","u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No IgG antibodies to {O} were found."],"borderline":["Equivocal","Equivocal","A borderline result. A repeat test in 2 to 4 weeks can clarify it."],"high":["Positive","Detected","IgG antibodies to {O} were found, which shows past exposure or vaccination."]}},"gl":"A negative result means no IgG antibodies to {O} were found. You may not have been exposed, or an infection may be too recent for antibodies to show.","gh":"A positive result means IgG antibodies to {O} were found. This usually reflects past infection or vaccination rather than current illness.","hi":"past infection with {O} or vaccination"}$j$),
('m:IGM', $j${"w":"The level of IgM antibodies to {O} in your blood. IgM antibodies are the first to appear and usually point to a recent or current infection.","a":"Timing of the test after symptoms start, a weakened immune system, cross-reacting antibodies from other infections and the laboratory method used.","s":"A positive IgM result suggests a recent or current infection with {O}. False positives occur, so results are often confirmed with IgG or other tests.","u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No IgM antibodies to {O} were found."],"borderline":["Equivocal","Equivocal","A borderline result. A repeat test in 1 to 2 weeks can clarify it."],"high":["Positive","Detected","IgM antibodies to {O} were found, which suggests recent infection."]}},"gl":"A negative result makes a recent infection with {O} less likely. Testing very early in an illness can miss antibodies, so a repeat test may be needed.","gh":"A positive result suggests a recent or current infection with {O}. Your clinician may confirm it with further tests.","hi":"recent infection with {O}"}$j$),
('m:IGA', $j${"w":"The level of IgA antibodies to {O} in your blood. IgA antibodies are linked with immune responses at mucous membranes, such as the gut.","a":"Time since exposure, a weakened immune system, IgA deficiency and the laboratory method used.","s":"A positive IgA result shows an immune response to {O}. It does not on its own confirm an active infection.","u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No IgA antibodies to {O} were found."],"high":["Positive","Detected","IgA antibodies to {O} were found."]}},"gl":"A negative result means no IgA antibodies to {O} were found.","gh":"A positive result shows an immune response to {O}. It does not on its own prove an active infection.","hi":"an immune response to {O}"}$j$),
('m:SER', $j${"w":"A blood test for antibodies to {O}. IgM antibodies point to a recent infection, while IgG antibodies show past infection or immunity.","a":"Time since infection or vaccination, a weakened immune system, cross-reacting antibodies and the laboratory method used.","s":"The pattern of antibodies shows whether infection with {O} is recent, past or absent.","u":"Qualitative (positive or negative)","rr":{"both":{"normal":["Negative","Not detected","No antibodies to {O} were found."],"high":["Positive","Detected","Antibodies to {O} were found. The antibody type shows whether infection is recent or past."]}},"gl":"No antibodies to {O} were found. This makes infection unlikely unless the test was taken very early in an illness.","gh":"Antibodies to {O} were found. IgM suggests a recent infection, and IgG alone suggests past infection or immunity.","hi":"recent or past infection with {O}"}$j$),
('m:AG', $j${"w":"A test that detects proteins (antigens) from {O} in your sample.","a":"Timing of the sample, the amount of organism present and the type of test used. Rapid antigen tests are less sensitive than PCR.","s":"A positive result shows that {O} is present. A negative antigen test does not fully rule out infection.","u":"Qualitative (detected or not detected)","rr":{"both":{"normal":["Not detected","Negative","No antigen from {O} was found."],"high":["Detected","Positive","Antigen from {O} was found, which points to current infection."]}},"gl":"No antigen from {O} was found. A negative result does not fully rule out infection, especially early on.","gh":"Antigen from {O} was found, which points to a current infection.","hi":"current infection with {O}"}$j$),
('m:CUL', $j${"w":"A laboratory culture of your sample to grow and identify {O}. Any organisms grown can be tested to see which antibiotics work.","a":"Recent antibiotics, how the sample was collected and stored, and the time taken to reach the laboratory.","s":"Growth of a disease-causing organism supports infection when it fits your symptoms. Normal flora or mixed growth often has no significance.","u":"Qualitative (organism and sensitivity report)","rr":{"both":{"normal":["No significant growth","Negative","No disease-causing organisms were grown."],"high":["Growth","Positive","A disease-causing organism was grown. The report lists which antibiotics will work."]}},"gl":"No significant growth means no disease-causing organisms were found.","gh":"A disease-causing organism was grown. The sensitivity report shows which antibiotics will work.","hi":"a bacterial or yeast infection"}$j$),
('m:MIC', $j${"w":"A microscope examination of your sample for {O}.","a":"How the sample was collected, recent treatment and the number of samples examined.","s":"Finding {O} supports a diagnosis when it fits your symptoms.","u":"Qualitative (seen or not seen)","rr":{"both":{"normal":["Not seen","Negative","None were seen in the sample."],"high":["Seen","Positive","The test found {O} in the sample."]}},"gl":"None were seen in the sample. One negative sample does not always rule out infection.","gh":"The test found {O} in your sample. Your clinician will decide whether this explains your symptoms.","hi":"infection or overgrowth"}$j$),
('m:RES', $j${"a":"Which organisms are present in the sample and how the sample was collected.","u":"Qualitative (detected or not detected)","r":"S","hi":"antibiotic-resistant bacteria"}$j$),
('c:GI', $j${"b":"ST","x":["Diarrhoea","Abdominal pain or cramps","Nausea or vomiting","Fever"],"f":["Wash hands with soap and water after using the toilet and before eating","Handle, store and cook food safely","Drink safe water when travelling"],"ug":"Seek urgent medical advice if you have bloody diarrhoea, a high fever, signs of dehydration or severe abdominal pain.","im":"Most gut infections settle with fluids and rest. Your clinician will advise if you need specific treatment.","r":"Only if symptoms continue or return, or if your clinician asks for a test after treatment.","z":["Ova, Cysts and Parasites"],"force":{"bs":"DG"}}$j$),
('c:RESP', $j${"b":"Nose and throat swab","x":["Cough","Sore throat","Runny or blocked nose","Fever","Shortness of breath"],"f":["Wash your hands often","Cover coughs and sneezes","Stay at home while you have a fever","Keep vaccinations up to date"],"ug":"Seek urgent medical advice if you have difficulty breathing, chest pain, confusion or a high fever that does not settle.","im":"Most respiratory infections clear with rest and fluids. Antibiotics only help bacterial infections, and antivirals help some cases of flu.","r":"Only if new symptoms develop. A repeat test is not needed to show you have recovered.","z":["Influenza A","Influenza B","Human Respiratory Syncytial Virus A"],"force":{"bs":"RS"}}$j$),
('c:UTI', $j${"b":"U","x":["Pain or burning when passing urine","Needing to pass urine often or urgently","Cloudy or strong-smelling urine","Lower abdominal pain"],"f":["Drink enough fluid to keep urine pale","Do not delay passing urine","Wipe from front to back after using the toilet"],"ug":"Seek urgent medical advice if you have fever, shivering, back or side pain, or feel very unwell, as this can mean a kidney infection.","im":"Urine infections are treated with antibiotics chosen from the culture and sensitivity results.","r":"After treatment only if symptoms continue or return, or if your clinician advises it.","z":["Urine culture","Urinalysis (Urine Examination)"],"force":{"bs":"RN"}}$j$),
('c:STI', $j${"b":"Urine or genital swab","x":["Often no symptoms","Unusual discharge","Pain when passing urine","Pelvic or testicular pain","Bleeding between periods or after sex"],"f":["Use condoms with new or casual partners","Test after a new partner and when you have symptoms","Tell recent partners if you test positive so they can be tested"],"ug":"Seek urgent medical advice if you have severe pelvic or testicular pain or a high fever, or if you are pregnant with symptoms.","im":"Most bacterial sexually transmitted infections are cured with antibiotics. Avoid sex until you and your partners have finished treatment.","r":"Test after any new sexual partner, at least once a year if you have new partners, and after treatment if your clinician advises it.","z":["Chlamydia trachomatis PCR","Neisseria gonorrhoeae PCR","HIV 1 & 2 Antibody/Antigen","Syphilis (Treponema Serology)"],"force":{"bs":"RP"}}$j$),
('c:GEN', $j${"b":"Genital swab","x":["Unusual discharge","Itching or soreness","Unpleasant odour","Pain when passing urine"],"f":["Avoid perfumed soaps, washes and douches","Wear loose cotton underwear","Use condoms with new partners"],"ug":"Seek urgent medical advice if you have a high fever or severe pelvic pain, or if you have symptoms during pregnancy.","im":"Treatment depends on the organism found. Many organisms found on swabs are normal and need no treatment.","r":"Only if symptoms continue after treatment or keep coming back.","z":["Female Genital Swab Culture","Chlamydia trachomatis PCR"],"force":{"bs":"RP"}}$j$),
('c:CERV', $j${"b":"Cervical or vaginal swab","x":["Usually no symptoms","Bleeding after sex or between periods when cell changes are present"],"f":["Attend NHS cervical screening when invited","Have the HPV vaccine if you are eligible","Stop smoking, which helps the body clear HPV"],"ug":"See your GP promptly if you have bleeding after sex, between periods or after the menopause, whatever your HPV result.","im":"There is no treatment for HPV itself. Follow-up checks find and treat cell changes long before cancer develops.","r":"Follow the NHS cervical screening programme. After a positive result you will usually have cytology or a colposcopy, then repeat HPV testing as advised.","z":["HPV High-Risk Genotyping","HPV 16 Genotype","HPV 18 Genotype"],"force":{"bs":"RP"}}$j$),
('c:BL', $j${"b":"S"}$j$),
('c:HEP', $j${"b":"S","x":["Often no symptoms","Yellowing of the skin and eyes (jaundice)","Dark urine","Tiredness","Abdominal discomfort"],"f":["Avoid alcohol to protect your liver","Never share needles, razors or toothbrushes","Use condoms"],"ug":"Seek urgent medical advice if you become drowsy or confused, bruise easily, vomit blood or develop jaundice.","im":"Your clinician will advise on monitoring and treatment. Hepatitis B can be controlled and hepatitis C can be cured with modern treatment.","force":{"bs":"LV"}}$j$),
('c:HIV', $j${"b":"S","x":["Often no symptoms","Flu-like illness 2 to 6 weeks after infection","Rash","Swollen glands"],"f":["Use condoms","Consider PrEP if you are at higher risk","Never share needles"],"ug":"If you think you have been exposed to HIV in the past 72 hours, get post-exposure prophylaxis (PEP) from a sexual health clinic or A&E straight away.","im":"HIV treatment is highly effective. People on effective treatment with an undetectable viral load cannot pass HIV on through sex.","z":["HIV 1 & 2 Antibody/Antigen","HIV Viral Load (HIV-1 RNA PCR)"],"force":{"bs":"IM"}}$j$),
